mapper.select:
SELECT , c.name as category_name FROM product p LEFT JOIN category c ON p.category_id = c.id
AND p.name LIKE CONCAT('%', #{name}, '%')
AND p.category_id = #{categoryId}
AND p.status = #{status}
ORDER BY p.create_time DESC

mapper.update:
UPDATE product
name = #{name}, category_id = #{categoryId}, description = #{description}, price = #{price}, original_price = #{originalPrice}, stock = #{stock}, sales = #{sales}, main_image = #{mainImage}, images = #{images}, status = #{status},
WHERE id = #{id}
